(function(root){
'use strict';
function body(page,data,C,K){
const E=C.escape,hero=(tag,title,text)=>`<div class="command-hero"><div class="eyebrow"><span class="live-dot"></span>TECH HORIZON / ${tag}</div><h1>${title}</h1><p>${text}</p></div>`;
const options=list=>list.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
const shortcuts=`<nav class="command-shortcuts" aria-label="Không gian làm việc"><a href="dieu-hanh.html">Kế hoạch nội dung</a><a href="studio.html">Studio</a><a href="bien-tap.html">Biên tập website</a><a href="du-lieu.html">Dữ liệu & hiển thị</a><a href="huong-dan.html">Hướng dẫn</a></nav>`;
if(page==='planner')return hero('TRẠM ĐIỀU HÀNH','Một nơi giữ ý tưởng.<br><span>Một nhịp làm nội dung.</span>','Lập kế hoạch, soạn dàn ý và theo dõi bài từ ý tưởng đến lúc đăng. Kế hoạch giữ trên trình duyệt này; lịch không tự đăng bài hoặc nhắc khi website đóng.')+shortcuts+`<div id="planner-storage-warning" class="command-warning" role="status" hidden></div><div class="command-stats"><div><strong id="planner-total">0</strong><span>TẤT CẢ KẾ HOẠCH</span></div><div><strong id="planner-ready">0</strong><span>SẴN SÀNG</span></div><div><strong id="planner-upcoming">0</strong><span>7 NGÀY SẮP TỚI</span></div><div><strong id="planner-overdue">0</strong><span>QUA MỐC DỰ KIẾN</span></div></div>
<div class="command-toolbar"><div><button class="button button-blue" id="new-task">+ Thêm ý tưởng</button><button class="button button-outline" id="planner-view" aria-pressed="false">Xem lịch tháng</button></div><div><button class="text-button" id="planner-ics">Xuất lịch ICS ↗</button><button class="text-button" id="planner-csv">Xuất bảng CSV ↗</button><a class="text-button" href="du-lieu.html">Sao lưu JSON ↗</a></div></div>
<div class="planner-filters"><label>Tìm kế hoạch<input id="planner-query" type="search" maxlength="100" placeholder="Tiêu đề, ghi chú, nguồn…"></label><label>Định dạng<select id="planner-format"><option value="all">Tất cả định dạng</option>${options(K.formats)}</select></label><label>Mốc thời gian<select id="planner-period"><option value="all">Mọi thời điểm</option><option value="upcoming">7 ngày sắp tới</option><option value="overdue">Qua mốc dự kiến</option><option value="unscheduled">Chưa đặt ngày</option></select></label></div><p class="command-caption" id="planner-result-count" role="status">0 mục</p>
<section id="planner-board" class="planner-board" aria-label="Tiến độ nội dung">${K.stages.map(([id,name])=>`<div class="planner-column"><h2>${name}<span data-stage-count="${id}">0</span></h2><div data-stage-list="${id}"></div></div>`).join('')}</section>
<section id="planner-calendar" hidden aria-label="Lịch nội dung"><div class="calendar-heading"><button class="button button-outline" id="month-previous" aria-label="Tháng trước">←</button><h2 id="calendar-month"></h2><button class="button button-outline" id="month-next" aria-label="Tháng sau">→</button><button class="text-button" id="month-today">Tháng hiện tại</button></div><p class="command-caption">Giờ Việt Nam (UTC+7) · Chọn một ngày để thêm kế hoạch.</p><div class="calendar-weekdays" aria-hidden="true">${['T2','T3','T4','T5','T6','T7','CN'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid" id="calendar-grid"></div><div class="calendar-mobile-list" id="calendar-mobile-list"></div></section>
<div class="command-empty" id="planner-empty"><span class="command-empty-icon">✳</span><h2>Ý tưởng đầu tiên bắt đầu ở đây.</h2><p>Thêm một câu hỏi bạn muốn giải thích. Bạn có thể đặt ngày sau và chuyển trạng thái ngay trên từng thẻ.</p><button class="text-button" data-new-task>Thêm kế hoạch đầu tiên ↗</button></div><p class="command-caption">Xuất ICS tạo sự kiện 30 phút trong lịch bạn nhập tệp vào, không gửi lời mời. Xuất lịch/bảng áp dụng cho các mục đang lọc. “Đã đăng” là trạng thái do bạn tự xác nhận.</p>
<dialog class="task-dialog" id="task-dialog" aria-labelledby="task-dialog-title"><form id="task-form"><div class="dialog-heading"><h2 id="task-dialog-title">Thêm kế hoạch</h2><button class="icon-button" type="button" id="close-task" aria-label="Đóng biểu mẫu">✕</button></div><div class="task-fields"><label class="full">Tiêu đề / ý tưởng<input id="task-title" name="title" required maxlength="180" placeholder="Một điều người đọc sẽ hiểu hoặc làm được"></label><label>Định dạng<select id="task-format" name="format">${options(K.formats)}</select></label><label>Tiến độ<select id="task-stage" name="stage">${options(K.stages)}</select></label><label class="full">Ngày giờ dự kiến (Việt Nam, UTC+7)<input id="task-due" name="due" type="datetime-local" min="2000-01-01T00:00" max="2099-12-31T23:59"><small>Để trống nếu chưa đặt lịch.</small></label><label class="full">Dàn ý / kịch bản<textarea id="task-notes" name="notes" rows="5" maxlength="5000" placeholder="Mở đầu → ý chính → ví dụ → điều muốn người xem thử"></textarea></label><label class="full">Nguồn cần kiểm tra<textarea id="task-sources" name="sources" rows="3" maxlength="3000" placeholder="Lưu đường dẫn và ghi chú đối chiếu tại đây"></textarea></label><label class="full">Đường dẫn bài đã đăng (tùy chọn)<input id="task-url" name="url" type="url" maxlength="2000" placeholder="https://…"></label></div><div class="task-form-actions"><button class="button button-blue" type="submit">Lưu kế hoạch</button><button class="text-button" id="task-duplicate" type="button" hidden>Nhân bản</button><button class="text-button danger-text" id="task-delete" type="button" hidden>Xóa mục này</button></div><p id="task-status" role="status" aria-live="polite"></p></form></dialog>`;
if(page==='settings')return hero('DỮ LIỆU & HIỂN THỊ','Dữ liệu của bạn.<br><span>Bạn giữ quyền chủ động.</span>','Sao lưu bản nháp, kế hoạch, phiếu thực hành, ghi chú và tùy chọn trong cùng một tệp. Giữ tệp riêng tư vì có thể chứa nội dung chưa đăng.')+shortcuts+`<section class="command-panel"><div class="command-panel-heading"><span class="section-index">01</span><div><h2>Đọc theo cách dễ chịu hơn.</h2><p>Các lựa chọn áp dụng trên thiết bị này, gồm cả bàn biên tập.</p></div></div><form id="preferences-form" class="preferences-form"><label>Cỡ giao diện<select id="preference-scale"><option value="1">Tiêu chuẩn</option><option value="1.12">Lớn hơn 12%</option><option value="1.25">Lớn hơn 25%</option></select></label><label>Chuyển động<select id="preference-motion"><option value="system">Theo cài đặt thiết bị</option><option value="reduce">Giảm chuyển động</option></select></label><label class="check-option"><input id="preference-contrast" type="checkbox">Tăng độ tương phản</label><button class="button button-blue" type="submit">Lưu hiển thị</button></form><p id="preferences-status" role="status"></p></section>
<section class="command-panel"><div class="command-panel-heading"><span class="section-index">02</span><div><h2>Một bản sao, đủ những gì cần giữ.</h2><p>Chọn nhóm dữ liệu để xuất hoặc khôi phục. Tệp sao lưu không bao gồm ảnh đang mở trong công cụ chuẩn bị ảnh.</p></div></div><fieldset class="backup-groups"><legend>Nhóm dữ liệu</legend>${Object.entries(K.groupNames).map(([id,name])=>`<label><input type="checkbox" data-backup-group="${id}" checked><span>${name}<small data-group-detail="${id}">Đang kiểm tra…</small></span></label>`).join('')}</fieldset><div class="command-toolbar"><button class="button button-blue" id="export-device">Tải bản sao lưu JSON ↗</button><label class="button button-outline file-button">Chọn tệp để khôi phục<input id="import-device" class="sr-only" type="file" accept="application/json,.json"></label></div><p class="command-caption" id="backup-last">Chưa ghi nhận lần tải sao lưu trên trình duyệt này.</p><div class="restore-preview" id="restore-preview" hidden><h3>Kiểm tra bản sao trước khi khôi phục.</h3><p id="restore-description"></p><p id="restore-groups"></p><p>Chỉ các nhóm đang chọn và có trong tệp mới bị thay thế. Hãy tải bản sao hiện tại trước khi tiếp tục.</p><button id="restore-device" class="button button-outline">Khôi phục các nhóm đã chọn</button><button id="cancel-restore" class="text-button">Hủy</button></div><p id="device-status" role="status" aria-live="polite"></p></section>
<section class="command-panel"><div class="command-panel-heading"><span class="section-index">03</span><div><h2>Kiểm tra trước khi đưa lên mạng.</h2><p>Đây là kiểm tra cấu hình, không phải đo hiệu năng hoặc lượng truy cập.</p></div></div><div id="health-results" class="health-results"></div><div class="command-toolbar"><a class="button button-outline" href="bien-tap.html">Mở bàn biên tập ↗</a><a class="text-button" href="huong-dan.html#xuat-ban">Xem hướng dẫn xuất bản ↗</a></div></section>
<section class="command-panel danger-panel"><h2>Xóa đúng nhóm, khi bạn cần.</h2><p>Chỉ xóa các nhóm đang chọn ở mục sao lưu. Thao tác này không xóa tệp website hoặc bản đang chạy online.</p><button class="button button-outline" id="clear-selected">Xóa các nhóm đã chọn</button></section>`;
if(page==='kit')return hero('GIỚI THIỆU & HỢP TÁC',E(data.config.name)+'.<br><span>Công nghệ gần hơn.</span>',E(data.config.description))+`<section class="kit-manifest"><div><span class="eyebrow">ĐIỀU CHÚNG TÔI THEO ĐUỔI</span><h2>Dễ hiểu để bắt đầu.<br>Có nguồn để tìm sâu.</h2><p>${E(data.config.tagline)}</p><p>Cẩm nang được trình bày theo tình huống, ví dụ và bước thực hành. Những giới hạn hoặc điều cần kiểm chứng được nói rõ trong nội dung.</p></div><div class="kit-monogram" aria-hidden="true"><span>TH</span><small>TECH HORIZON</small></div></section><section class="kit-topics"><h2>Các mảng nội dung.</h2><div>${data.categories.map(c=>`<article><span>${E(c.short||c.name)}</span><h3>${E(c.name)}</h3><p>${E(c.description)}</p></article>`).join('')}</div></section><section class="command-panel"><h2>Những gì bạn có thể khám phá ngay.</h2><div class="command-stats"><div><strong>${data.articles.length}</strong><span>CẨM NANG</span></div><div><strong>${data.categories.length}</strong><span>CHUYÊN MỤC</span></div><div><strong>${data.journeys?.length||0}</strong><span>LỘ TRÌNH</span></div><div><strong>${data.glossary?.length||0}</strong><span>THUẬT NGỮ</span></div></div><p class="command-caption">Các con số phản ánh nội dung website. Website chưa hiển thị số người theo dõi, lượt tiếp cận hoặc báo giá hợp tác.</p><button class="button button-outline" id="download-kit">Tải hồ sơ giới thiệu TXT ↗</button><a class="text-button" href="index.html#bai-viet">Đọc cẩm nang ↗</a></section>
<section class="command-panel" id="hop-tac"><div class="command-panel-heading"><span class="section-index">TH</span><div><h2>Bắt đầu từ một lời giới thiệu.</h2><p>Điền đề xuất để tạo nội dung liên hệ. Bạn tự gửi qua email hoặc kênh chính thức sau khi xem lại.</p></div></div><div class="tool-grid"><form id="brief-form" class="tool-form"><div class="field"><label for="brief-name">Tên / đơn vị</label><input id="brief-name" name="sender" required maxlength="150"></div><div class="field"><label for="brief-type">Bạn muốn trao đổi về</label><select id="brief-type" name="kind"><option>Gợi ý chủ đề</option><option>Hợp tác nội dung</option><option>Góp ý / sửa thông tin</option></select></div><div class="field full"><label for="brief-message">Nội dung đề xuất</label><textarea id="brief-message" name="message" rows="5" required maxlength="3000"></textarea></div><button type="submit" class="button button-blue">Soạn nội dung liên hệ</button></form><div class="tool-result"><label for="brief-output">Bản nháp để bạn xem lại</label><textarea id="brief-output" readonly rows="10" placeholder="Nội dung sẽ xuất hiện tại đây."></textarea><div class="command-toolbar"><button class="button button-outline" id="copy-brief" disabled>Sao chép</button><a class="button button-outline" id="email-brief" hidden>Mở ứng dụng email ↗</a></div><p id="brief-status" role="status">${data.config.email?'Email công khai đã được chủ kênh cấu hình.':'Chủ kênh chưa cấu hình email công khai. Bạn có thể sao chép nội dung để gửi qua kênh chính thức.'}</p></div></div></section>`;
return hero('HƯỚNG DẪN VẬN HÀNH','Mở là dùng.<br><span>Nắm rõ để tự quản lý.</span>','Từ chỉnh thông tin kênh tới xuất website, đây là các bước để bạn tự vận hành Tech Horizon mỗi ngày.')+shortcuts+`<nav class="guide-jump" aria-label="Mục lục hướng dẫn">${[['bat-dau','Bắt đầu'],['doc-va-thu','Đọc & thực hành'],['lam-noi-dung','Làm nội dung'],['anh','Chuẩn bị ảnh'],['xuat-ban','Xuất bản'],['sao-luu','Sao lưu'],['gioi-han','Phạm vi hoạt động']].map(([id,name])=>`<a href="#${id}">${name} ↘</a>`).join('')}</nav>
<section class="command-panel guide-section" id="bat-dau"><span class="eyebrow">01 / ĐẶT NỀN</span><h2>Để website mang đúng tên kênh.</h2><ol><li>Mở <a href="bien-tap.html">Bàn biên tập</a>, kiểm tra tên, thông điệp và mô tả.</li><li>Dán URL Facebook chính thức; thêm email bạn muốn công khai. Không điền mật khẩu hay mã đăng nhập.</li><li>Chọn logo, ảnh bìa và màu nhấn; nhấn Lưu bản nháp.</li><li>Mở Xem trước để kiểm tra. Bản nháp này chỉ nằm trên trình duyệt bạn đang dùng.</li></ol><a class="text-button" href="du-lieu.html">Kiểm tra cấu hình hiện tại ↗</a></section>
<section class="command-panel guide-section" id="doc-va-thu"><span class="eyebrow">TH / KHÁM PHÁ THEO NHU CẦU</span><h2>Một bài nên đọc, một việc để thử.</h2><p>Ở đầu trang chủ, chọn chủ đề trong ô Bạn có 5 phút? để mở một cẩm nang. Phần <a href="index.html#diem-bat-dau">Khám phá theo nhu cầu</a> lọc theo chủ đề, mục tiêu và thời gian; bài đầu được gợi ý để bắt đầu. Sao chép lựa chọn để gửi đường dẫn mở lại đúng bộ lọc.</p><p>Mở <a href="thuc-hanh.html">Trạm thực hành</a>, chọn nhiệm vụ, đọc phần cần hiểu rồi mở công cụ Studio. Cẩm nang và công cụ ở trong phiếu mở ở tab mới để giữ dấu chọn/ghi chép tại trang phiếu. Phiếu tự lưu trên trình duyệt này, gồm dấu chọn và ghi chép. Dấu chọn do bạn tự đánh giá, không phải kiểm tra tự động. Tải TXT hoặc dùng nhóm Phiếu & ghi chép thực hành trong Dữ liệu & hiển thị để giữ bản sao riêng. Nếu tab khác đã sửa phiếu, tải TXT để giữ thay đổi đang nhập trước khi đọc lại dữ liệu đã lưu.</p><p>Cuối mỗi cẩm nang có hướng thực hành và bài đọc tiếp theo nếu có. Các mục đã đọc chỉ phản ánh tiến độ trên trình duyệt này.</p></section>
<section class="command-panel guide-section" id="lam-noi-dung"><span class="eyebrow">02 / TẠO MỘT NHỊP ĐỀU</span><h2>Từ ý tưởng tới bài hoàn chỉnh.</h2><ol><li>Tạo kế hoạch tại <a href="dieu-hanh.html">Trạm điều hành</a>; chọn định dạng, dàn ý, nguồn và ngày giờ Việt Nam.</li><li>Dùng Studio để soạn prompt hoặc ước lượng thời lượng kịch bản. Mẫu prompt cần được bạn mang sang công cụ AI mình dùng.</li><li>Kiểm tra nguồn, biên tập và dùng danh sách rà soát trước khi đăng. Bàn biên tập có bảng rà soát nguồn, tóm tắt, mục lục và mô tả ảnh của bản nháp đã lưu. Nếu bản nháp đã thay đổi ở tab khác, tải tệp phục hồi biểu mẫu trước khi tải lại trang.</li><li>Với cẩm nang website, thêm bài ở Bàn biên tập; với Facebook, bạn đăng chủ động trên Facebook rồi dán liên kết thật vào website.</li><li>Chuyển kế hoạch sang Đã đăng sau khi hoàn tất. Lịch không tự xác minh trạng thái Facebook.</li></ol><p>Xuất ICS để nhập mốc dự kiến sang ứng dụng lịch. Tệp không có lời mời hoặc thông báo được gửi tự động; cập nhật trên website không tự cập nhật lịch đã nhập.</p></section>
<section class="command-panel guide-section" id="anh"><span class="eyebrow">03 / CHUẨN BỊ HÌNH ẢNH</span><h2>Chọn khung, xem lại và tải ảnh.</h2><p>Mở <a href="studio.html#media">Chuẩn bị ảnh</a>, chọn ảnh từ thiết bị, chọn tỷ lệ, chiều rộng và định dạng. Công cụ cắt giữa khung; hãy kiểm tra bản xem trước để tránh mất chữ hoặc chủ thể. Nếu có chữ tiếng Việt trên ảnh, dùng ảnh gốc đủ nét.</p><p>Bàn biên tập nhận PNG, JPEG hoặc WebP: logo tối đa 150 KB, ảnh bài 250 KB, ảnh bìa 400 KB. Dùng công cụ ảnh để giảm kích thước/chất lượng khi cần. Mức giảm dung lượng thay đổi theo ảnh.</p><p>Công cụ chỉ xử lý ảnh bạn chọn; không tăng chi tiết thật của ảnh nhỏ và không tự tải ảnh từ trang khác.</p></section>
<section class="command-panel guide-section" id="xuat-ban"><span class="eyebrow">04 / ĐƯA NỘI DUNG ĐẾN NGƯỜI ĐỌC</span><h2>Lưu nháp → xem trước → xuất ZIP.</h2><ol><li>Lưu các biểu mẫu trong Bàn biên tập và kiểm tra bản xem trước.</li><li>Nhấn Xuất toàn bộ website ZIP, giải nén toàn bộ rồi mở index.html.</li><li>Để cập nhật hosting của bạn, tải toàn bộ nội dung thư mục website trong ZIP lên thư mục web tĩnh.</li><li>Đặt đúng địa chỉ website trong cấu hình trước khi xuất để canonical, sitemap và RSS khớp với nơi chạy.</li><li>Nếu nhờ Codex cập nhật bản Sites, yêu cầu cập nhật trên đường dẫn hiện tại. Tải ZIP từ bàn biên tập không tự thay thế bản đang online.</li></ol><p>Giữ tệp theo cùng cấu trúc thư mục; không chỉ gửi riêng index.html. Bản mở bằng file:// có thể bị trình duyệt giới hạn sao chép, giọng đọc hoặc cách lưu dữ liệu. Chạy npm start trên máy có Node.js hoặc dùng hosting HTTPS để có ngữ cảnh ổn định hơn.</p></section>
<section class="command-panel guide-section" id="sao-luu"><span class="eyebrow">05 / GIỮ CÔNG SỨC CỦA BẠN</span><h2>Sao lưu trước khi đổi máy hoặc xóa trình duyệt.</h2><p>Mở <a href="du-lieu.html">Dữ liệu & hiển thị</a>, chọn nhóm cần giữ rồi tải JSON. Trên trình duyệt mới, chọn tệp, xem thông tin và khôi phục nhóm mong muốn. Chỉ khôi phục tệp do bạn tin cậy tạo ra.</p><p>ZIP website chứa nội dung công khai; bản sao lưu thiết bị có thể chứa ghi chú, dàn ý và kế hoạch chưa đăng. Cất riêng bản sao lưu, không đưa lên thư mục web công khai.</p><p>Nếu hết dung lượng bộ nhớ, hãy tải sao lưu, giảm số lượng hoặc kích thước ảnh nhúng và kiểm tra cài đặt trình duyệt. Lịch sử biên tập chỉ giữ tối đa ba trạng thái khi còn chỗ.</p></section>
<section class="command-panel guide-section" id="gioi-han"><span class="eyebrow">06 / PHẠM VI HOẠT ĐỘNG</span><h2>Những gì đang có trong bản này.</h2><div class="capability-table"><table><thead><tr><th>Chức năng</th><th>Cách hoạt động</th></tr></thead><tbody><tr><td>Cẩm nang, tìm kiếm, lộ trình</td><td>Trang tĩnh, đọc và tìm trên dữ liệu website.</td></tr><tr><td>Biên tập, lịch, ghi chú</td><td>Lưu trong trình duyệt; có sao lưu và khôi phục bằng tệp.</td></tr><tr><td>Phiếu thực hành</td><td>Tự lưu trên trình duyệt; tải TXT hoặc sao lưu JSON cùng dữ liệu thiết bị.</td></tr><tr><td>Studio</td><td>Xử lý cục bộ. Không tự gọi AI hoặc tải nội dung lên máy chủ xử lý.</td></tr><tr><td>Facebook & liên hệ</td><td>Mở đường dẫn chính thức hoặc ứng dụng email khi bạn chọn.</td></tr><tr><td>Đăng nhập, đồng bộ nhiều thiết bị, tự đăng Facebook</td><td>Chưa có máy chủ hoặc tích hợp API cho các tác vụ này.</td></tr><tr><td>Quyền truy cập bản Sites</td><td>Theo thiết lập chia sẻ hiện tại của chủ website; nội dung ZIP có thể được bạn lưu trữ riêng.</td></tr></tbody></table></div></section>`;
}
function studioExtras(){return `<section class="tool-panel" id="media" role="tabpanel" aria-labelledby="studio-tab-media" hidden><div class="tool-panel-heading"><div><span class="eyebrow">05 / MỘT HÌNH ẢNH, ĐÚNG KHUNG</span><h2>Chuẩn bị ảnh để đăng.</h2></div><p>Đổi kích thước, cắt giữa khung và xuất ảnh ngay trên thiết bị. Hãy xem lại chủ thể và chữ trước khi tải.</p></div><div class="tool-grid"><form id="media-form" class="tool-form"><div class="field full"><label for="media-file">Ảnh gốc PNG / JPEG / WebP (tối đa 15 MB)</label><input id="media-file" type="file" accept="image/png,image/jpeg,image/webp" required></div><div class="field"><label for="media-ratio">Tỷ lệ khung</label><select id="media-ratio"><option value="1">Vuông · 1:1</option><option value="0.8">Dọc · 4:5</option><option value="0.5625">Dọc dài · 9:16</option><option value="1.7777777778">Ngang · 16:9</option></select></div><div class="field"><label for="media-width">Chiều rộng xuất (px)</label><input id="media-width" type="number" min="64" max="2048" step="1" value="1080" required></div><div class="field"><label for="media-type">Định dạng</label><select id="media-type"><option value="image/webp">WebP</option><option value="image/jpeg">JPEG</option><option value="image/png">PNG</option></select></div><div class="field"><label for="media-quality">Chất lượng <span id="media-quality-value">82%</span></label><input id="media-quality" type="range" min="20" max="100" value="82"><small>PNG không dùng mức chất lượng này.</small></div><button type="submit" class="button button-blue">Tạo ảnh xem trước</button><p id="media-status" class="full" role="status"></p></form><div class="tool-result media-result"><div class="media-placeholder" id="media-placeholder">Ảnh xem trước sẽ nằm ở đây.<br>Ảnh không được gửi lên dịch vụ bên ngoài.</div><canvas id="media-canvas" hidden aria-label="Ảnh sau khi cắt và đổi kích thước"></canvas><p id="media-details" role="status"></p><button class="button button-outline" id="download-media" disabled>Tải ảnh ↗</button></div></div></section>
<section class="tool-panel" id="script" role="tabpanel" aria-labelledby="studio-tab-script" hidden><div class="tool-panel-heading"><div><span class="eyebrow">06 / TÌM NHỊP CHO CÂU CHUYỆN</span><h2>Kịch bản này đọc trong bao lâu?</h2></div><p>Ước tính theo các cụm tách bằng khoảng trắng và tốc độ bạn chọn. Hãy đọc thử để chốt thời lượng thực tế.</p></div><div class="tool-grid"><form id="script-form" class="tool-form"><div class="field full"><label for="script-text">Nội dung kịch bản</label><textarea id="script-text" maxlength="30000" rows="12" placeholder="Dán hoặc soạn nội dung cần đọc…"></textarea></div><div class="field"><label for="script-speed">Tốc độ đọc (đơn vị / phút)</label><input id="script-speed" type="number" min="60" max="300" value="150" required></div><div class="field"><label for="script-target">Thời lượng mong muốn (giây)</label><input id="script-target" type="number" min="1" max="3600" value="60" required></div><div class="command-toolbar full"><button class="button button-blue" type="submit">Tính thời lượng</button><button class="text-button" type="button" id="save-script">Lưu nháp trên thiết bị</button><button class="text-button" type="button" id="download-script">Tải TXT ↗</button></div><p class="full" id="script-status" role="status"></p></form><div class="tool-result"><span class="eyebrow">THỜI LƯỢNG ƯỚC TÍNH</span><strong class="script-duration" id="script-duration">0 giây</strong><div class="script-metrics"><div><strong id="script-units">0</strong><span>ĐƠN VỊ KHOẢNG TRẮNG</span></div><div><strong id="script-characters">0</strong><span>KÝ TỰ UNICODE</span></div></div><p id="script-target-result">Nhập nội dung để so với thời lượng mục tiêu.</p><p class="command-caption">Tiếng Việt có từ gồm nhiều tiếng; chỉ số này không phải phép đếm từ ngôn ngữ học. Tốc độ 150 là giá trị khởi đầu bạn có thể đổi, không phải chuẩn bắt buộc.</p></div></div></section>`;}
const api={body,studioExtras};if(typeof module==='object'&&module.exports)module.exports=api;else root.THCreatorMarkup=api;
})(typeof window!=='undefined'?window:globalThis);
